class MiniMaxH3Server:
    @modal.enter()
    def start(self) -> None:
        download_model()
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

        environment = os.environ.copy()
        gpu_count = get_int_env("MINIMAX_H3_GPU_COUNT", 1, 1)
        if gpu_count != 1:
            raise RuntimeError("MINIMAX_H3_GPU_COUNT must be 1 for this deployment; configure multiple GPUs in the Modal app for multi-GPU")
        visible_devices = environment.get("CUDA_VISIBLE_DEVICES") or ",".join(str(index) for index in range(gpu_count))
        existing_pythonpath = environment.get("PYTHONPATH")
        pythonpath_entries = [str(VLLM_OMNI_DIR)]
        if existing_pythonpath:
            pythonpath_entries.append(existing_pythonpath)
        video_sync_timeout = environment.get("VLLM_OMNI_VIDEO_SYNC_TIMEOUT") or str(
            get_int_env("MINIMAX_H3_VIDEO_SYNC_TIMEOUT_SECONDS", DEFAULT_STARTUP_TIMEOUT_SECONDS, 1)
        )

        environment.update(
            {
                "CUDA_VISIBLE_DEVICES": visible_devices,
