def terminate_process(process: subprocess.Popen[str], grace_seconds: int = 30) -> None:
    if process.poll() is not None:
        return

    try:
        process.terminate()
    except ProcessLookupError:
        return

    try:
        process.wait(timeout=grace_seconds)
        return
    except subprocess.TimeoutExpired:
        pass

    try:
        process.kill()
    except ProcessLookupError:
        return

    try:
        process.wait(timeout=grace_seconds)
    except subprocess.TimeoutExpired:
