            "MINIMAX_H3_CONNECT_TIMEOUT_SECONDS",
            DEFAULT_CONNECT_TIMEOUT_SECONDS,
            1.0,
        )

        @asynccontextmanager
        async def lifespan(_: FastAPI):
            client_state["client"] = httpx.AsyncClient(
                timeout=httpx.Timeout(request_timeout_seconds, connect=connect_timeout_seconds),
                limits=httpx.Limits(max_connections=128, max_keepalive_connections=32),
            )
            try:
                yield
            finally:
                client = client_state.pop("client", None)
                if isinstance(client, httpx.AsyncClient):
                    await client.aclose()

        server = FastAPI(
            title="MiniMax-H3 OpenAI-Compatible Video API",
            version="1.0.0",
            lifespan=lifespan,
        )

        hop_by_hop_request_headers = {
            "host",
            "content-length",
            "connection",
            "keep-alive",
            "proxy-authenticate",
            "proxy-authorization",
            "te",
            "trailer",
            "transfer-encoding",
            "upgrade",
            "accept-encoding",
        }
        hop_by_hop_response_headers = {
            "connection",
            "keep-alive",
            "proxy-authenticate",
            "proxy-authorization",
            "te",
            "trailer",
            "transfer-encoding",
            "upgrade",
        }

        def get_http_client() -> httpx.AsyncClient:
            client = client_state.get("client")
            if not isinstance(client, httpx.AsyncClient):
                raise HTTPException(status_code=503, detail="HTTP client is not ready")
            return client

        def ensure_process_alive() -> None:
            process = getattr(self, "process", None)
            if isinstance(process, subprocess.Popen) and process.poll() is not None:
                raise HTTPException(status_code=503, detail=f"vLLM-Omni process exited with code {process.returncode}")

        def remove_header(headers: dict[str, str], header_name: str) -> None:
            normalized = header_name.lower()
            for key in list(headers.keys()):
                if key.lower() == normalized:
                    headers.pop(key, None)

        def make_upstream_headers(request: Request) -> dict[str, str]:
            headers: dict[str, str] = {}
            has_request_id = False
            for key, value in request.headers.items():
                lower_key = key.lower()
                if lower_key in hop_by_hop_request_headers:
                    continue
                if lower_key == "x-request-id":
                    has_request_id = True
                headers[key] = value
            headers["accept-encoding"] = "identity"
            if not has_request_id:
                headers["x-request-id"] = str(uuid.uuid4())
            return headers

        def filter_response_headers(
            upstream: httpx.Response,
            include_content_length: bool = True,
            include_content_encoding: bool = True,
        ) -> list[tuple[str, str]]:
            headers: list[tuple[str, str]] = []
            for key, value in upstream.headers.multi_items():
                lower_key = key.lower()
                if lower_key in hop_by_hop_response_headers:
                    continue
                if lower_key == "content-length" and not include_content_length:
                    continue
                if lower_key == "content-encoding" and not include_content_encoding:
                    continue
                headers.append((key, value))
            return headers

        def apply_response_headers(response: Response, headers: list[tuple[str, str]]) -> Response:
            response.raw_headers = [(key.encode("latin-1"), value.encode("latin-1")) for key, value in headers]
            return response

        def endpoint_with_query(endpoint: str, request: Request) -> str:
            if request.url.query:
                separator = "&" if "?" in endpoint else "?"
                return f"{endpoint}{separator}{request.url.query}"
            return endpoint

        def upstream_url(endpoint: str) -> str:
            return f""

        def is_json_content_type(content_type: str | None) -> bool:
            if not content_type:
                return False
            media_type = content_type.split(";", 1)[0].strip().lower()
            return media_type == "application/json" or media_type.endswith("+json")

        def normalize_response_format(value: Any) -> VideoResponseFormat:
            if value == "url":
                return "url"
            if value == "b64_json":
                return "b64_json"
            return "binary"

        async def read_body_and_response_format(request: Request) -> tuple[bytes, VideoResponseFormat]:
            body = await request.body()
            response_format = normalize_response_format(request.query_params.get("response_format"))
            if response_format == "binary" and body and is_json_content_type(request.headers.get("content-type")):
                try:
                    payload = json.loads(body)
                except json.JSONDecodeError:
                    return body, response_format
                if isinstance(payload, dict):
                    response_format = normalize_response_format(payload.get("response_format"))
            return body, response_format

        def extension_for_content_type(content_type: str | None) -> str:
            if not content_type:
                return ".bin"
            media_type = content_type.split(";", 1)[0].strip().lower()
            mapping = {
                "video/mp4": ".mp4",
                "video/webm": ".webm",
                "video/quicktime": ".mov",
                "image/png": ".png",
                "image/jpeg": ".jpg",
                "audio/wav": ".wav",
                "audio/x-wav": ".wav",
                "audio/mpeg": ".mp3",
                "application/json": ".json",
            }
            return mapping.get(media_type, ".bin")

        def content_type_for_path(path: Path) -> str:
            mapping = {
                ".mp4": "video/mp4",
                ".webm": "video/webm",
                ".mov": "video/quicktime",
                ".png": "image/png",
                ".jpg": "image/jpeg",
                ".jpeg": "image/jpeg",
                ".wav": "audio/wav",
                ".mp3": "audio/mpeg",
                ".json": "application/json",
            }
            return mapping.get(path.suffix.lower(), "application/octet-stream")

        def filename_with_extension(name: str, content_type: str | None) -> str:
            if Path(name).suffix:
                return name
            return f"{name}{extension_for_content_type(content_type)}"

        def make_b64_payload(file_id: str, filename: str, content: bytes, content_type: str) -> JSONPayload:
            return {
                "object": "file",
                "id": file_id,
                "filename": filename,
                "content_type": content_type,
                "b64_json": base64.b64encode(content).decode("ascii"),
            }

        async def commit_output_volume_async(raise_on_error: bool = False) -> None:
            await asyncio.to_thread(commit_output_volume, raise_on_error)

        async def persist_output_bytes(content: bytes, content_type: str | None) -> tuple[str, Path]:
            OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
            file_id = f"file-{uuid.uuid4().hex}"
            path = OUTPUT_DIR / filename_with_extension(file_id, content_type)
            await asyncio.to_thread(path.write_bytes, content)
            await commit_output_volume_async(True)
            return file_id, path

        def resolve_output_file(file_path: str) -> Path:
            root = OUTPUT_DIR.resolve()
            candidate = (root / file_path).resolve()
            try:
                candidate.relative_to(root)
            except ValueError as exc:
                raise HTTPException(status_code=404, detail="File not found") from exc
            if not candidate.is_file():
                raise HTTPException(status_code=404, detail="File not found")
            return candidate

        async def finalize_stream(upstream: httpx.Response, commit_after_success: bool) -> None:
            try:
                await upstream.aclose()
            finally:
                if commit_after_success and 200 <= upstream.status_code < 300:
                    await commit_output_volume_async(False)

        async def forward(
            request: Request,
            endpoint: str,
            commit_after_success: bool = False,
            content: bytes | None = None,
        ) -> Response:
            ensure_process_alive()
            client = get_http_client()
            request_content = await request.body() if content is None else content
            target_endpoint = endpoint_with_query(endpoint, request)
            headers = make_upstream_headers(request)
            try:
                upstream_request = client.build_request(
                    request.method,
                    upstream_url(target_endpoint),
                    content=request_content,
                    headers=headers,
                )
                upstream = await client.send(upstream_request, stream=True)
            except httpx.HTTPError as exc:
                raise HTTPException(status_code=503, detail=str(exc)) from exc

            response = StreamingResponse(
                upstream.aiter_raw(),
                status_code=upstream.status_code,
                background=BackgroundTask(finalize_stream, upstream, commit_after_success),
            )
            return apply_response_headers(response, filter_response_headers(upstream))

        async def buffered_upstream_request(
            method: str,
            request: Request,
            endpoint: str,
            content: bytes | None = None,
            headers: dict[str, str] | None = None,
        ) -> httpx.Response:
            ensure_process_alive()
            client = get_http_client()
            request_content = await request.body() if content is None else content
            request_headers = headers if headers is not None else make_upstream_headers(request)
            try:
                return await client.request(
                    method,
                    upstream_url(endpoint_with_query(endpoint, request)),
                    content=request_content,
                    headers=request_headers,
                )
            except httpx.HTTPError as exc:
                raise HTTPException(status_code=503, detail=str(exc)) from exc

        async def formatted_buffered_response(
            request: Request,
            upstream: httpx.Response,
            response_format: VideoResponseFormat,
            suggested_filename: str,
        ) -> Response:
            content_type = upstream.headers.get("content-type") or "application/octet-stream"
            if 200 <= upstream.status_code < 300 and not is_json_content_type(content_type):
                if response_format == "b64_json":
                    file_id = f"file-{uuid.uuid4().hex}"
                    filename = filename_with_extension(suggested_filename or file_id, content_type)
                    return JSONResponse(
                        make_b64_payload(file_id, filename, upstream.content, content_type),
                        status_code=upstream.status_code,
                    )
                if response_format == "url":
                    file_id, path = await persist_output_bytes(upstream.content, content_type)
                    relative_path = str(path.relative_to(OUTPUT_DIR.resolve()))
                    return JSONResponse(
                        {
                            "object": "file",
                            "id": file_id,
                            "filename": path.name,
                            "content_type": content_type,
                            "url": str(request.url_for("output_file", file_path=relative_path)),
                        },
                        status_code=upstream.status_code,
                    )

            response = Response(
                content=upstream.content,
                status_code=upstream.status_code,
            )
            return apply_response_headers(
                response,
                filter_response_headers(
                    upstream,
                    include_content_length=False,
                    include_content_encoding=False,
                ),
            )

        @server.get("/health")
        async def health() -> JSONResponse:
            ensure_process_alive()
            try:
                response = await get_http_client().get(f"")
                response.raise_for_status()
            except httpx.HTTPError as exc:
