        @server.api_route("/v1/videos/sync", methods=["POST"])
        async def videos_sync(request: Request) -> Response:
            body, response_format = await read_body_and_response_format(request)
            if response_format in {"url", "b64_json"}:
                upstream = await buffered_upstream_request("POST", request, "/v1/videos/sync", content=body)
                if 200 <= upstream.status_code < 300:
                    await commit_output_volume_async(False)
                return await formatted_buffered_response(request, upstream, response_format, "video")
            return await forward(request, "/v1/videos/sync", commit_after_success=True, content=body)

        @server.post("/v1/videos/sync/form")
        async def videos_sync_form(
            request: Request,
            prompt: Annotated[str, Form()],
            model: Annotated[str, Form()] = MODEL_ID,
            response_format: Annotated[VideoResponseFormat, Form()] = "binary",
            negative_prompt: Annotated[str | None, Form()] = None,
            duration: Annotated[float | None, Form()] = None,
            fps: Annotated[int | None, Form()] = None,
            seed: Annotated[int | None, Form()] = None,
            resolution: Annotated[str | None, Form()] = None,
            task_type: Annotated[str | None, Form()] = None,
            extra_json: Annotated[str | None, Form()] = None,
            image: Annotated[UploadFile | None, File()] = None,
            first_frame: Annotated[UploadFile | None, File()] = None,
            last_frame: Annotated[UploadFile | None, File()] = None,
            reference_image: Annotated[UploadFile | None, File()] = None,
            reference_audio: Annotated[UploadFile | None, File()] = None,
            audio: Annotated[UploadFile | None, File()] = None,
        ) -> Response:
            fields: dict[str, Any] = {"model": model, "prompt": prompt}
            if response_format != "binary":
                fields["response_format"] = response_format

            optional_fields: dict[str, Any] = {
                "negative_prompt": negative_prompt,
                "duration": duration,
                "fps": fps,
                "seed": seed,
                "resolution": resolution,
                "task_type": task_type,
            }
            for key, value in optional_fields.items():
                if value is not None:
                    fields[key] = value

            if extra_json:
                try:
                    extra_fields = json.loads(extra_json)
                except json.JSONDecodeError as exc:
                    raise HTTPException(status_code=400, detail="extra_json must be valid JSON") from exc
                if not isinstance(extra_fields, dict):
                    raise HTTPException(status_code=400, detail="extra_json must decode to a JSON object")
                for key, value in extra_fields.items():
                    if value is not None:
                        fields[str(key)] = value

            form_fields: dict[str, str] = {}
            for key, value in fields.items():
                if isinstance(value, str):
                    form_fields[key] = value
                elif isinstance(value, bool):
                    form_fields[key] = "true" if value else "false"
                elif isinstance(value, (dict, list)):
                    form_fields[key] = json.dumps(value)
                else:
                    form_fields[key] = str(value)

            upload_fields = {
                "image": image,
                "first_frame": first_frame,
                "last_frame": last_frame,
                "reference_image": reference_image,
                "reference_audio": reference_audio,
                "audio": audio,
            }
            files: list[tuple[str, tuple[str, bytes, str]]] = []
            for field_name, upload in upload_fields.items():
                if upload is None:
                    continue
                filename = upload.filename or f"{field_name}.bin"
                content_type = upload.content_type or "application/octet-stream"
                data = b""
                try:
                    data = await upload.read()
                finally:
                    await upload.close()
                if data:
                    files.append((field_name, (filename, data, content_type)))

            headers = make_upstream_headers(request)
            remove_header(headers, "content-type")
            remove_header(headers, "content-length")

            try:
                upstream = await get_http_client().post(
                    upstream_url(endpoint_with_query("/v1/videos/sync", request)),
                    data=form_fields,
                    files=files if files else None,
                    headers=headers,
                )
            except httpx.HTTPError as exc:
                raise HTTPException(status_code=503, detail=str(exc)) from exc

            if 200 <= upstream.status_code < 300:
                await commit_output_volume_async(False)

            return await formatted_buffered_response(request, upstream, response_format, "video")

        @server.get("/v1/videos/{video_id}")
        async def video_status(video_id: str, request: Request) -> Response:
            return await forward(request, f"/v1/videos/{quote(video_id, safe='')}", commit_after_success=True)

        @server.get("/v1/files/{file_id}")
        async def retrieve_file(file_id: str, request: Request) -> Response:
            response_format = normalize_response_format(request.query_params.get("response_format"))
            endpoint = f"/v1/files/{quote(file_id, safe='')}"
            if response_format in {"url", "b64_json"}:
                upstream = await buffered_upstream_request("GET", request, endpoint)
                if 200 <= upstream.status_code < 300:
                    await commit_output_volume_async(False)
                return await formatted_buffered_response(request, upstream, response_format, file_id)
            return await forward(request, endpoint, commit_after_success=True)

        @server.get("/outputs/{file_path:path}", name="output_file")
        async def output_file(
            file_path: str,
            request: Request,
            disposition: FileDisposition = "inline",
            response_format: VideoResponseFormat = "binary",
        ) -> Response:
            path = resolve_output_file(file_path)
            content_type = content_type_for_path(path)
            file_id = path.stem
            relative_path = str(path.relative_to(OUTPUT_DIR.resolve()))

            if response_format == "b64_json":
                data = await asyncio.to_thread(path.read_bytes)
                return JSONResponse(make_b64_payload(file_id, path.name, data, content_type))

            if response_format == "url":
                return JSONResponse(
                    {
                        "object": "file",
                        "id": file_id,
                        "filename": path.name,
                        "content_type": content_type,
                        "url": str(request.url_for("output_file", file_path=relative_path)),
                    }
                )

            return FileResponse(path, filename=path.name, content_disposition_type=disposition)

        return server


