model_volume = modal.Volume.from_name("minimax-h3-model", create_if_missing=True)
output_volume = modal.Volume.from_name("minimax-h3-outputs", create_if_missing=True)

_DOWNLOAD_LOCK = threading.Lock()
_OUTPUT_LOCK = threading.Lock()


def require_env(name: str) -> str:
    value = os.environ.get(name)
    if not value:
        raise RuntimeError(f"Missing required environment variable: {name}")
    return value


def get_int_env(name: str, default: int, minimum: int = 0) -> int:
    value = os.environ.get(name)
    if value is None or value == "":
        return default
    try:
        parsed = int(value)
    except ValueError as exc:
        raise RuntimeError(f"{name} must be an integer") from exc
    if parsed < minimum:
        raise RuntimeError(f"{name} must be at least {minimum}")
    return parsed


def get_float_env(name: str, default: float, minimum: float = 0.0) -> float:
    value = os.environ.get(name)
    if value is None or value == "":
        return default
    try:
        parsed = float(value)
    except ValueError as exc:
        raise RuntimeError(f"{name} must be a number") from exc
    if parsed < minimum:
        raise RuntimeError(f"{name} must be at least {minimum}")
    return parsed


def get_bool_env(name: str, default: bool) -> bool:
    value = os.environ.get(name)
    if value is None or value == "":
        return default
    normalized = value.strip().lower()
    if normalized in {"1", "true", "yes", "y", "on"}:
        return True
    if normalized in {"0", "false", "no", "n", "off"}:
        return False
    raise RuntimeError(f"{name} must be a boolean value")


def directory_has_file(path: Path) -> bool:
    if not path.is_dir():
        return False
    try:
        for child in path.rglob("*"):
            if child.is_file():
                return True
    except OSError:
        return False
    return False


def missing_model_requirements() -> list[str]:
    required_paths = [
        MODEL_DIR / "model_index.json",
        MODEL_DIR / "FL2VA",
        MODEL_DIR / "Ref2VA",
        MODEL_DIR / "text_encoder",
        MODEL_DIR / "processor",
        MODEL_DIR / "tokenizer",
        MODEL_DIR / "video_vae",
        MODEL_DIR / "audio_vae",
    ]
    missing: list[str] = []
    for path in required_paths:
        if path.suffix:
            if not path.is_file():
                missing.append(str(path))
        else:
            if not directory_has_file(path):
                missing.append(str(path))
    return missing


def model_is_downloaded() -> bool:
    return not missing_model_requirements()


def download_model() -> None:
    from huggingface_hub import snapshot_download

    with _DOWNLOAD_LOCK:
        if model_is_downloaded():
            return

        token = os.environ.get("HF_TOKEN")
        if not token and get_bool_env("MINIMAX_H3_REQUIRE_HF_TOKEN", True):
            token = require_env("HF_TOKEN")

        MODEL_DIR.parent.mkdir(parents=True, exist_ok=True)

        snapshot_kwargs: dict[str, Any] = {
            "repo_id": MODEL_ID,
            "local_dir": str(MODEL_DIR),
        }
        if token:
            snapshot_kwargs["token"] = token

        snapshot_download(**snapshot_kwargs)

        missing = missing_model_requirements()
        if missing:
            raise RuntimeError(f"Model download did not produce required paths: {', '.join(missing)}")

        model_volume.commit()


def commit_output_volume(raise_on_error: bool = False) -> None:
    with _OUTPUT_LOCK:
        try:
            if OUTPUT_DIR.exists():
                output_volume.commit()
        except Exception:
            if raise_on_error:
                raise


def terminate_process(process: subprocess.Popen[str], grace_seconds: int = 30) -> None:
    def send_process_signal(signal_number: int) -> None:
        if os.name == "posix":
            os.killpg(process.pid, signal_number)
        elif signal_number == signal.SIGTERM:
            process.terminate()
        else:
            process.kill()

    if process.poll() is not None:
        return

    try:
        send_process_signal(signal.SIGTERM)
    except ProcessLookupError:
        return

    try:
        process.wait(timeout=grace_seconds)
        return
    except subprocess.TimeoutExpired:
        pass

    try:
        send_process_signal(getattr(signal, "SIGKILL", signal.SIGTERM))
    except ProcessLookupError:
        return

    try:
        process.wait(timeout=grace_seconds)
    except subprocess.TimeoutExpired:
        pass


def wait_for_server(process: subprocess.Popen[str], timeout_seconds: int) -> None:
    deadline = time.monotonic() + timeout_seconds
    while time.monotonic() < deadline:
        if process.poll() is not None:
            return_code = process.returncode
            terminate_process(process, 5)
            raise RuntimeError(f"vLLM-Omni exited during startup with code {return_code}")

        probe_returncode = 1
        try:
            probe = subprocess.run(
                [
                    "curl",
                    "--fail",
                    "--silent",
                    "--show-error",
                    "--max-time",
                    "5",
                    f"",
                ],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                check=False,
                timeout=10,
            )
            probe_returncode = probe.returncode
        except (OSError, subprocess.TimeoutExpired):
            probe_returncode = 1

        if probe_returncode == 0:
            return

        time.sleep(5)

    terminate_process(process, 30)
    raise TimeoutError("Timed out waiting for vLLM-Omni to become healthy")


def get_vllm_executable(environment: dict[str, str] | None = None) -> str:
    executable = shutil.which("vllm", path=environment.get("PATH") if environment else None)
    if not executable:
        raise RuntimeError("vLLM executable was not found on PATH")
    return executable


def get_vllm_serve_help(environment: dict[str, str], executable: str) -> str:
    try:
        completed = subprocess.run(
            [executable, "serve", "--help"],
            env=environment,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            timeout=120,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError("Timed out while reading vLLM serve help output") from exc

    if completed.returncode != 0:
        raise RuntimeError(f"Unable to read vLLM serve help output: {completed.stdout}")

    return completed.stdout


def help_supports_flag(help_text: str, flag: str) -> bool:
    return flag in help_text


def append_if_supported(command: list[str], help_text: str, flag: str, *values: Any) -> bool:
    if not help_supports_flag(help_text, flag):
        return False
    command.append(flag)
    command.extend(str(value) for value in values)
    return True


def append_required_flag(command: list[str], help_text: str, flag: str, *values: Any) -> None:
    if not append_if_supported(command, help_text, flag, *values):
        raise RuntimeError(f"Installed vLLM-Omni does not support required flag {flag}")


def build_vllm_command(environment: dict[str, str]) -> list[str]:
    executable = get_vllm_executable(environment)
    help_text = get_vllm_serve_help(environment, executable)
    command = [executable, "serve", str(MODEL_DIR)]

    gpu_count = get_int_env("MINIMAX_H3_GPU_COUNT", 1, 1)
    if gpu_count != 1:
        raise RuntimeError("MINIMAX_H3_GPU_COUNT must be 1 for this deployment")

    append_required_flag(command, help_text, "--omni")
    append_required_flag(command, help_text, "--host", "0.0.0.0")
    append_required_flag(command, help_text, "--port", str(PORT))
    append_required_flag(command, help_text, "--trust-remote-code")

    task_type = (os.environ.get("MINIMAX_H3_TASK_TYPE") or "").strip().lower()
    if task_type:
        if task_type not in {"fl2va", "ref2va"}:
            raise RuntimeError("MINIMAX_H3_TASK_TYPE must be either fl2va or ref2va when set")
        append_required_flag(command, help_text, "--task-type", task_type)

    append_if_supported(command, help_text, "--served-model-name", MODEL_ID)

    if help_supports_flag(help_text, "--num-gpus"):
        append_if_supported(command, help_text, "--num-gpus", gpu_count)
    elif help_supports_flag(help_text, "--tensor-parallel-size"):
        append_if_supported(command, help_text, "--tensor-parallel-size", gpu_count)

    if help_supports_flag(help_text, "--gpu-memory-utilization"):
        gpu_memory_utilization = (
            os.environ.get("VLLM_GPU_MEMORY_UTILIZATION")
            or os.environ.get("MINIMAX_H3_GPU_MEMORY_UTILIZATION")
            or "0.95"
        )
        append_if_supported(command, help_text, "--gpu-memory-utilization", gpu_memory_utilization)

    if get_bool_env("MINIMAX_H3_ENABLE_CPU_OFFLOAD", True):
        if not append_if_supported(command, help_text, "--enable-cpu-offload"):
            cpu_offload_gb = os.environ.get("VLLM_CPU_OFFLOAD_GB") or os.environ.get("MINIMAX_H3_CPU_OFFLOAD_GB")
            if cpu_offload_gb and help_supports_flag(help_text, "--cpu-offload-gb"):
                append_if_supported(command, help_text, "--cpu-offload-gb", cpu_offload_gb)

    diffusion_attention_backend = os.environ.get("MINIMAX_H3_DIFFUSION_ATTENTION_BACKEND") or "FLASH_ATTN"
    append_if_supported(command, help_text, "--diffusion-attention-backend", diffusion_attention_backend)

    init_timeout_seconds = get_int_env("MINIMAX_H3_INIT_TIMEOUT_SECONDS", DEFAULT_STARTUP_TIMEOUT_SECONDS, 1)
    append_if_supported(command, help_text, "--init-timeout", init_timeout_seconds)

    max_model_len = os.environ.get("VLLM_MAX_MODEL_LEN") or os.environ.get("MINIMAX_H3_MAX_MODEL_LEN")
    if max_model_len:
        append_if_supported(command, help_text, "--max-model-len", max_model_len)

    allowed_local_media_path = os.environ.get("VLLM_ALLOWED_LOCAL_MEDIA_PATH") or str(OUTPUT_DIR)
    append_if_supported(command, help_text, "--allowed-local-media-path", allowed_local_media_path)

    text_encoder_tp_size = os.environ.get("MINIMAX_H3_TEXT_ENCODER_TP_SIZE") or os.environ.get("VLLM_TEXT_ENCODER_TP_SIZE")
    if text_encoder_tp_size:
        append_if_supported(command, help_text, "--text-encoder-tp-size", text_encoder_tp_size)

    vae_patch_parallel_size = os.environ.get("MINIMAX_H3_VAE_PATCH_PARALLEL_SIZE") or os.environ.get("VLLM_VAE_PATCH_PARALLEL_SIZE")
    if vae_patch_parallel_size:
        append_if_supported(command, help_text, "--vae-patch-parallel-size", vae_patch_parallel_size)
    vae_parallel_mode = os.environ.get("MINIMAX_H3_VAE_PARALLEL_MODE") or os.environ.get("VLLM_VAE_PARALLEL_MODE")
    if vae_parallel_mode:
        append_if_supported(command, help_text, "--vae-parallel-mode", vae_parallel_mode)
    if get_bool_env("MINIMAX_H3_VAE_USE_TILING", True):
        append_if_supported(command, help_text, "--vae-use-tiling")

    if get_bool_env("MINIMAX_H3_ENFORCE_EAGER", False):
        append_if_supported(command, help_text, "--enforce-eager")

    return command


@app.cls(
    gpu="H200",
    timeout=6 * 60 * 60,
    scaledown_window=DEFAULT_SCALEDOWN_WINDOW_SECONDS,
    min_containers=0,
    max_containers=1,
    volumes={"/models": model_volume, "/outputs": output_volume},
    secrets=[modal.Secret.from_name("minimax-h3-secrets")],
    image=image,
)
class MiniMaxH3Server:
    @modal.enter()
    def start(self) -> None:
        download_model()
        OUTPUT_DIR.mkdir(parents=True, exist_ok=True)

        environment = os.environ.copy()
        gpu_count = get_int_env("MINIMAX_H3_GPU_COUNT", 1, 1)
        if gpu_count != 1:
            raise RuntimeError("MINIMAX_H3_GPU_COUNT must be 1 for this deployment")
        visible_devices = environment.get("CUDA_VISIBLE_DEVICES") or ",".join(str(index) for index in range(gpu_count))
        existing_pythonpath = environment.get("PYTHONPATH")
        pythonpath_entries = [str(VLLM_OMNI_DIR)]
        if existing_pythonpath:
            pythonpath_entries.append(existing_pythonpath)
        video_sync_timeout = environment.get("VLLM_OMNI_VIDEO_SYNC_TIMEOUT") or str(
            get_int_env("MINIMAX_H3_VIDEO_SYNC_TIMEOUT_SECONDS", DEFAULT_STARTUP_TIMEOUT_SECONDS, 1)
        )

        environment.update(
            {
                "CUDA_VISIBLE_DEVICES": visible_devices,
                "VLLM_WORKER_MULTIPROC_METHOD": "spawn",
                "VLLM_OMNI_VIDEO_SYNC_TIMEOUT": video_sync_timeout,
                "VLLM_OMNI_OUTPUT_DIR": str(OUTPUT_DIR),
                "VLLM_OMNI_VIDEO_OUTPUT_DIR": str(OUTPUT_DIR),
                "PYTHONPATH": os.pathsep.join(pythonpath_entries),
            }
        )

        command = build_vllm_command(environment)

        self.process = subprocess.Popen(
            command,
            env=environment,
            stdout=None,
            stderr=None,
            text=True,
            start_new_session=os.name == "posix",
        )
        wait_for_server(self.process, get_int_env("MINIMAX_H3_STARTUP_TIMEOUT_SECONDS", DEFAULT_STARTUP_TIMEOUT_SECONDS, 1))

    @modal.exit()
    def stop(self) -> None:
        process = getattr(self, "process", None)
        if isinstance(process, subprocess.Popen):
            terminate_process(process, 30)
        commit_output_volume()

    @modal.asgi_app(label="minimax-h3-openai", requires_proxy_auth=True)
    def api(self):
        import httpx
        from fastapi import FastAPI, File, Form, HTTPException, Request, UploadFile
        from fastapi.responses import FileResponse, JSONResponse, Response, StreamingResponse
        from starlette.background import BackgroundTask

        client_state: dict[str, Any] = {}
        request_timeout_seconds = get_float_env(
            "MINIMAX_H3_REQUEST_TIMEOUT_SECONDS",
            DEFAULT_REQUEST_TIMEOUT_SECONDS,
            1.0,
        )
        connect_timeout_seconds = get_float_env(
            "MINIMAX_H3_CONNECT_TIMEOUT_SECONDS",
            DEFAULT_CONNECT_TIMEOUT_SECONDS,
            1.0,
        )

        @asynccontextmanager
        async def lifespan(_: FastAPI):
            client_state["client"] = httpx.AsyncClient(
                timeout=httpx.Timeout(request_timeout_seconds, connect=connect_timeout_seconds),
                limits=httpx.Limits(max_connections=128, max_keepalive_connections=32),
            )
            try:
                yield
            finally:
                client = client_state.pop("client", None)
                if isinstance(client, httpx.AsyncClient):
                    await client.aclose()

        server = FastAPI(
            title="MiniMax-H3 OpenAI-Compatible Video API",
            version="1.0.0",
            lifespan=lifespan,
        )

        hop_by_hop_request_headers = {
            "host",
            "content-length",
            "connection",
            "keep-alive",
            "proxy-authenticate",
            "proxy-authorization",
            "te",
            "trailer",
            "transfer-encoding",
            "upgrade",
            "accept-encoding",
        }
        hop_by_hop_response_headers = {
            "connection",
            "keep-alive",
            "proxy-authenticate",
            "proxy-authorization",
            "te",
            "trailer",
            "transfer-encoding",
            "upgrade",
        }

        def get_http_client() -> httpx.AsyncClient:
            client = client_state.get("client")
            if not isinstance(client, httpx.AsyncClient):
                raise HTTPException(status_code=503, detail="HTTP client is not ready")
            return client

        def ensure_process_alive() -> None:
            process = getattr(self, "process", None)
            if isinstance(process, subprocess.Popen) and process.poll() is not None:
                raise HTTPException(status_code=503, detail=f"vLLM-Omni process exited with code {process.returncode}")

        def remove_header(headers: dict[str, str], header_name: str) -> None:
            normalized = header_name.lower()
            for key in list(headers.keys()):
                if key.lower() == normalized:
                    headers.pop(key, None)

        def make_upstream_headers(request: Request) -> dict[str, str]:
            headers: dict[str, str] = {}
            has_request_id = False
            for key, value in request.headers.items():
                lower_key = key.lower()
                if lower_key in hop_by_hop_request_headers:
                    continue
                if lower_key == "x-request-id":
                    has_request_id = True
                headers[key] = value
            headers["accept-encoding"] = "identity"
            if not has_request_id:
                headers["x-request-id"] = str(uuid.uuid4())
            return headers

        def filter_response_headers(
            upstream: httpx.Response,
            include_content_length: bool = True,
            include_content_encoding: bool = True,
        ) -> list[tuple[str, str]]:
            headers: list[tuple[str, str]] = []
            for key, value in upstream.headers.multi_items():
                lower_key = key.lower()
                if lower_key in hop_by_hop_response_headers:
                    continue
                if lower_key == "content-length" and not include_content_length:
                    continue
                if lower_key == "content-encoding" and not include_content_encoding:
                    continue
                headers.append((key, value))
            return headers

        def apply_response_headers(response: Response, headers: list[tuple[str, str]]) -> Response:
            response.raw_headers = [(key.encode("latin-1"), value.encode("latin-1")) for key, value in headers]
            return response

        def endpoint_with_query(endpoint: str, request: Request) -> str:
            if request.url.query:
                separator = "&" if "?" in endpoint else "?"
                return f"{endpoint}{separator}{request.url.query}"
            return endpoint

        def upstream_url(endpoint: str) -> str:
            return f""

        def is_json_content_type(content_type: str | None) -> bool:
            if not content_type:
                return False
            media_type = content_type.split(";", 1)[0].strip().lower()
            return media_type == "application/json" or media_type.endswith("+json")

        def normalize_response_format(value: Any) -> VideoResponseFormat:
            if value == "url":
                return "url"
            if value == "b64_json":
                return "b64_json"
            return "binary"

        def normalize_task(value: Any) -> str | None:
            if value is None:
                return None
            task = str(value).strip().lower()
            if not task:
                return None
            if task not in SUPPORTED_TASKS:
                raise HTTPException(status_code=400, detail="task must be one of t2va, fl2va, ref2va")
            return task

        def ensure_task_compatibility(task: str) -> None:
            served_task = normalize_task(os.environ.get("MINIMAX_H3_TASK_TYPE"))
            if served_task is None:
                return
            if served_task == "fl2va" and task not in {"t2va", "fl2va"}:
                raise HTTPException(status_code=400, detail="The server is configured for FL2VA task family only")
            if served_task == "ref2va" and task != "ref2va":
                raise HTTPException(status_code=400, detail="The server is configured for Ref2VA task family only")

        async def read_body_and_response_format(request: Request) -> tuple[bytes, VideoResponseFormat]:
            body = await request.body()
            response_format = normalize_response_format(request.query_params.get("response_format"))
            if response_format == "binary" and body and is_json_content_type(request.headers.get("content-type")):
                try:
                    payload = json.loads(body)
                except json.JSONDecodeError:
                    return body, response_format
                if isinstance(payload, dict):
                    response_format = normalize_response_format(payload.get("response_format"))
            return body, response_format

        def extension_for_content_type(content_type: str | None) -> str:
            if not content_type:
                return ".bin"
            media_type = content_type.split(";", 1)[0].strip().lower()
            mapping = {
                "video/mp4": ".mp4",
                "video/webm": ".webm",
                "video/quicktime": ".mov",
                "image/png": ".png",
                "image/jpeg": ".jpg",
                "audio/wav": ".wav",
                "audio/x-wav": ".wav",
                "audio/mpeg": ".mp3",
                "application/json": ".json",
            }
            return mapping.get(media_type, ".bin")

        def content_type_for_path(path: Path) -> str:
            mapping = {
                ".mp4": "video/mp4",
                ".webm": "video/webm",
                ".mov": "video/quicktime",
                ".png": "image/png",
                ".jpg": "image/jpeg",
                ".jpeg": "image/jpeg",
                ".wav": "audio/wav",
                ".mp3": "audio/mpeg",
                ".json": "application/json",
            }
            return mapping.get(path.suffix.lower(), "application/octet-stream")

        def filename_with_extension(name: str, content_type: str | None) -> str:
            if Path(name).suffix:
                return name
            return f"{name}{extension_for_content_type(content_type)}"

        def make_b64_payload(file_id: str, filename: str, content: bytes, content_type: str) -> JSONPayload:
            return {
                "object": "file",
                "id": file_id,
                "filename": filename,
                "content_type": content_type,
                "b64_json": base64.b64encode(content).decode("ascii"),
            }

        async def commit_output_volume_async(raise_on_error: bool = False) -> None:
            await asyncio.to_thread(commit_output_volume, raise_on_error)

        async def persist_output_bytes(content: bytes, content_type: str | None) -> tuple[str, Path]:
            OUTPUT_DIR.mkdir(parents=True, exist_ok=True)
            file_id = f"file-{uuid.uuid4().hex}"
            path = OUTPUT_DIR / filename_with_extension(file_id, content_type)
            await asyncio.to_thread(path.write_bytes, content)
            await commit_output_volume_async(True)
            return file_id, path

        def resolve_output_file(file_path: str) -> Path:
            root = OUTPUT_DIR.resolve()
            candidate = (root / file_path).resolve()
            try:
                candidate.relative_to(root)
            except ValueError as exc:
                raise HTTPException(status_code=404, detail="File not found") from exc
            if not candidate.is_file():
                raise HTTPException(status_code=404, detail="File not found")
            return candidate

        async def finalize_stream(upstream: httpx.Response, commit_after_success: bool) -> None:
            try:
                await upstream.aclose()
            finally:
                if commit_after_success and 200 <= upstream.status_code < 300:
                    await commit_output_volume_async(False)

        async def forward(
            request: Request,
            endpoint: str,
            commit_after_success: bool = False,
            content: bytes | None = None,
        ) -> Response:
            ensure_process_alive()
            client = get_http_client()
            request_content = await request.body() if content is None else content
            target_endpoint = endpoint_with_query(endpoint, request)
            headers = make_upstream_headers(request)
            try:
                upstream_request = client.build_request(
                    request.method,
                    upstream_url(target_endpoint),
                    content=request_content,
                    headers=headers,
                )
                upstream = await client.send(upstream_request, stream=True)
            except httpx.HTTPError as exc:
                raise HTTPException(status_code=503, detail=str(exc)) from exc

            response = StreamingResponse(
                upstream.aiter_raw(),
                status_code=upstream.status_code,
                background=BackgroundTask(finalize_stream, upstream, commit_after_success),
            )
            return apply_response_headers(response, filter_response_headers(upstream))

        async def buffered_upstream_request(
            method: str,
            request: Request,
            endpoint: str,
            content: bytes | None = None,
            headers: dict[str, str] | None = None,
        ) -> httpx.Response:
            ensure_process_alive()
            client = get_http_client()
            request_content = await request.body() if content is None else content
            request_headers = headers if headers is not None else make_upstream_headers(request)
            try:
                return await client.request(
                    method,
                    upstream_url(endpoint_with_query(endpoint, request)),
                    content=request_content,
                    headers=request_headers,
                )
            except httpx.HTTPError as exc:
                raise HTTPException(status_code=503, detail=str(exc)) from exc

        async def formatted_buffered_response(
            request: Request,
            upstream: httpx.Response,
            response_format: VideoResponseFormat,
            suggested_filename: str,
        ) -> Response:
            content_type = upstream.headers.get("content-type") or "application/octet-stream"
            if 200 <= upstream.status_code < 300 and not is_json_content_type(content_type):
                if response_format == "b64_json":
                    file_id = f"file-{uuid.uuid4().hex}"
                    filename = filename_with_extension(suggested_filename or file_id, content_type)
                    return JSONResponse(
                        make_b64_payload(file_id, filename, upstream.content, content_type),
                        status_code=upstream.status_code,
                    )
                if response_format == "url":
                    file_id, path = await persist_output_bytes(upstream.content, content_type)
                    relative_path = str(path.relative_to(OUTPUT_DIR.resolve()))
                    return JSONResponse(
                        {
                            "object": "file",
                            "id": file_id,
                            "filename": path.name,
                            "content_type": content_type,
                            "url": str(request.url_for("output_file", file_path=relative_path)),
                        },
                        status_code=upstream.status_code,
                    )

            response = Response(
                content=upstream.content,
                status_code=upstream.status_code,
            )
            return apply_response_headers(
                response,
                filter_response_headers(
                    upstream,
                    include_content_length=False,
                    include_content_encoding=False,
                ),
            )

        def parse_json_object(value: str | None, field_name: str) -> dict[str, Any]:
            if value is None or value == "":
                return {}
            try:
                parsed = json.loads(value)
            except json.JSONDecodeError as exc:
                raise HTTPException(status_code=400, detail=f"{field_name} must be valid JSON") from exc
            if not isinstance(parsed, dict):
                raise HTTPException(status_code=400, detail=f"{field_name} must decode to a JSON object")
            return parsed

        def validate_prompt(prompt: str) -> str:
            normalized = prompt.strip()
            if not normalized:
                raise HTTPException(status_code=400, detail="prompt is required")
            if len(normalized) > MAX_PROMPT_CHARS:
                raise HTTPException(status_code=400, detail=f"prompt must be at most {MAX_PROMPT_CHARS} characters")
            return normalized

        def validate_dimensions(width: int | None, height: int | None) -> None:
            if width is None and height is None:
                return
            if width is None or height is None:
                raise HTTPException(status_code=400, detail="width and height must be provided together")
            if width <= 0 or height <= 0:
                raise HTTPException(status_code=400, detail="width and height must be positive")
            if width % 32 != 0 or height % 32 != 0:
                raise HTTPException(status_code=400, detail="width and height must be multiples of 32")
            ratio = width / height
            if ratio < 0.25 or ratio > 4.0:
                raise HTTPException(status_code=400, detail="width and height aspect ratio must be between 1:4 and 4:1")

        def validate_generation_options(
            duration: float | None,
            fps: int | None,
            num_inference_steps: int | None,
            flow_shift: float | None,
            audio_flow_shift: float | None,
            width: int | None,
            height: int | None,
        ) -> None:
            validate_dimensions(width, height)
            if duration is not None and (duration < 4.0 or duration > 15.0):
                raise HTTPException(status_code=400, detail="duration must be between 4 and 15 seconds")
            if fps is not None and fps != DEFAULT_FPS:
                raise HTTPException(status_code=400, detail="fps must be 24")
            if num_inference_steps is not None and num_inference_steps < 1:
                raise HTTPException(status_code=400, detail="num_inference_steps must be at least 1")
            if flow_shift is not None and flow_shift <= 0:
                raise HTTPException(status_code=400, detail="flow_shift must be greater than 0")
            if audio_flow_shift is not None and audio_flow_shift <= 0:
                raise HTTPException(status_code=400, detail="audio_flow_shift must be greater than 0")

        async def read_upload(upload: UploadFile, field_name: str) -> tuple[str, bytes, str]:
            filename = upload.filename or f"{field_name}.bin"
            content_type = upload.content_type or "application/octet-stream"
            try:
                data = await upload.read()
            finally:
                await upload.close()
            size_limit = MAX_VIDEO_BYTES
            media_type = content_type.split(";", 1)[0].strip().lower()
            if media_type.startswith("image/") or field_name in {"image", "first_frame", "last_frame"}:
                size_limit = MAX_IMAGE_BYTES
            elif media_type.startswith("audio/") or field_name in {"audio", "audio_reference"}:
                size_limit = MAX_AUDIO_BYTES
            elif media_type.startswith("video/") or field_name in {"video", "videos"}:
                size_limit = MAX_VIDEO_BYTES
            if len(data) > size_limit:
                raise HTTPException(status_code=413, detail=f"{field_name} exceeds size limit")
            return filename, data, content_type

        async def collect_named_files(
            field_name: str,
            uploads: list[UploadFile] | None,
        ) -> list[tuple[str, tuple[str, bytes, str]]]:
            parts: list[tuple[str, tuple[str, bytes, str]]] = []
            total_bytes = 0
            if not uploads:
                return parts
            for upload in uploads:
                filename, data, content_type = await read_upload(upload, field_name)
                total_bytes += len(data)
                if total_bytes > MAX_TOTAL_UPLOAD_BYTES:
                    raise HTTPException(status_code=413, detail="Uploaded files exceed request size limit")
                if data:
                    parts.append((field_name, (filename, data, content_type)))
            return parts

        async def collect_optional_file(
            field_name: str,
            upload: UploadFile | None,
        ) -> list[tuple[str, tuple[str, bytes, str]]]:
            if upload is None:
                return []
            return await collect_named_files(field_name, [upload])

        def merge_extra_params(
            task: str,
            duration: float | None,
            audio_flow_shift: float | None,
            aspect_ratio: str | None,
            extra_params_json: str | None,
            extra_json: str | None,
        ) -> dict[str, Any]:
            merged = parse_json_object(extra_params_json, "extra_params")
            extra_additional = parse_json_object(extra_json, "extra_json")
            merged.update(extra_additional)
            merged["task"] = task
            if duration is not None:
                merged["duration"] = duration
            if audio_flow_shift is not None:
                merged["audio_flow_shift"] = audio_flow_shift
            if aspect_ratio is not None and aspect_ratio != "":
                merged["aspect_ratio"] = aspect_ratio
            return merged

        def infer_task(
            task: str | None,
            image: UploadFile | None,
            first_frame: UploadFile | None,
            last_frame: UploadFile | None,
            reference_image: UploadFile | None,
            reference_images: list[UploadFile] | None,
            reference_audio: UploadFile | None,
            audio: UploadFile | None,
            video: UploadFile | None,
            videos: list[UploadFile] | None,
        ) -> str:
            normalized_task = normalize_task(task)
            if normalized_task is not None:
                return normalized_task
            reference_image_count = (1 if reference_image is not None else 0) + (len(reference_images) if reference_images else 0)
            reference_video_count = (1 if video is not None else 0) + (len(videos) if videos else 0)
            has_audio_reference = reference_audio is not None or audio is not None
            has_fl2va_frames = image is not None or first_frame is not None or last_frame is not None
            if reference_video_count > 0 or reference_image_count > 0 or has_audio_reference:
                if reference_video_count > 0 or has_audio_reference:
                    return "ref2va"
            if has_fl2va_frames:
                return "fl2va"
            return "t2va"

        def build_base_fields(
            prompt: str,
            model: str,
            width: int | None,
            height: int | None,
            fps: int | None,
            num_inference_steps: int | None,
            flow_shift: float | None,
            seed: int | None,
            extra_params: dict[str, Any],
        ) -> dict[str, str]:
            fields: dict[str, str] = {
                "model": model,
                "prompt": validate_prompt(prompt),
                "fps": str(DEFAULT_FPS if fps is None else fps),
                "num_inference_steps": str(DEFAULT_NUM_INFERENCE_STEPS if num_inference_steps is None else num_inference_steps),
                "flow_shift": str(DEFAULT_FLOW_SHIFT if flow_shift is None else flow_shift),
                "extra_params": json.dumps(extra_params, separators=(",", ":")),
            }
            if width is not None:
                fields["width"] = str(width)
            if height is not None:
                fields["height"] = str(height)
            if seed is not None:
                fields["seed"] = str(seed)
            return fields

        async def send_multipart_request(
            request: Request,
            endpoint: str,
            form_fields: dict[str, str],
            files: list[tuple[str, tuple[str, bytes, str]]],
            response_format: VideoResponseFormat,
            suggested_filename: str,
            commit_after_success: bool = True,
        ) -> Response:
            ensure_process_alive()
            headers = make_upstream_headers(request)
            remove_header(headers, "content-type")
            remove_header(headers, "content-length")
            try:
                upstream = await get_http_client().post(
                    upstream_url(endpoint_with_query(endpoint, request)),
                    data=form_fields,
                    files=files if files else None,
                    headers=headers,
                )
            except httpx.HTTPError as exc:
                raise HTTPException(status_code=503, detail=str(exc)) from exc

            if commit_after_success and 200 <= upstream.status_code < 300:
                await commit_output_volume_async(False)

            return await formatted_buffered_response(request, upstream, response_format, suggested_filename)

        async def build_fl2va_files(
            image: UploadFile | None,
            first_frame: UploadFile | None,
            last_frame: UploadFile | None,
        ) -> list[tuple[str, tuple[str, bytes, str]]]:
            resolved_first_frame = first_frame if first_frame is not None else image
            files: list[tuple[str, tuple[str, bytes, str]]] = []
            files.extend(await collect_optional_file("first_frame", resolved_first_frame))
            files.extend(await collect_optional_file("last_frame", last_frame))
            return files

        async def build_ref2va_image_audio_files(
            reference_image: UploadFile | None,
            reference_images: list[UploadFile] | None,
            reference_audio: UploadFile | None,
            audio: UploadFile | None,
            image: UploadFile | None,
        ) -> list[tuple[str, tuple[str, bytes, str]]]:
            merged_images: list[UploadFile] = []
            if reference_image is not None:
                merged_images.append(reference_image)
            if reference_images:
                merged_images.extend(reference_images)
            if image is not None and not merged_images:
                merged_images.append(image)
            if len(merged_images) != 1:
                raise HTTPException(status_code=400, detail="Current Ref2VA image+audio path requires exactly one image")
            resolved_audio = reference_audio if reference_audio is not None else audio
            if resolved_audio is None:
                raise HTTPException(status_code=400, detail="Current Ref2VA image+audio path requires one audio reference")
            files: list[tuple[str, tuple[str, bytes, str]]] = []
            files.extend(await collect_named_files("image", merged_images))
            files.extend(await collect_optional_file("audio_reference", resolved_audio))
            return files

        async def build_ref2va_video_files(
            video: UploadFile | None,
            videos: list[UploadFile] | None,
        ) -> list[tuple[str, tuple[str, bytes, str]]]:
            merged_videos: list[UploadFile] = []
            if video is not None:
                merged_videos.append(video)
            if videos:
                merged_videos.extend(videos)
            if not merged_videos:
                raise HTTPException(status_code=400, detail="At least one reference video is required")
            if len(merged_videos) > 3:
                raise HTTPException(status_code=400, detail="At most three reference videos are supported")
            return await collect_named_files("videos", merged_videos)

        @server.get("/health")
        async def health() -> JSONResponse:
            ensure_process_alive()
            try:
                response = await get_http_client().get(f"")
                response.raise_for_status()
            except httpx.HTTPError as exc:
                raise HTTPException(status_code=503, detail=str(exc)) from exc

            try:
                upstream_payload: Any = json.loads(response.text) if response.text else None
            except json.JSONDecodeError:
                upstream_payload = response.text

            return JSONResponse({"status": "ok", "model": MODEL_ID, "upstream": upstream_payload})

