        @server.api_route("/v1/videos/sync", methods=["POST"])
        async def videos_sync(request: Request) -> Response:
            body, response_format = await read_body_and_response_format(request)
            if response_format in {"url", "b64_json"}:
                upstream = await buffered_upstream_request("POST", request, "/v1/videos/sync", content=body)
                if 200 <= upstream.status_code < 300:
                    await commit_output_volume_async(False)
                return await formatted_buffered_response(request, upstream, response_format, "video")
            return await forward(request, "/v1/videos/sync", commit_after_success=True, content=body)

